-- The ISO add-on's tables, part 1 (docs/iso/model.md §1-3.4, §3.8, §6; ISO-2d): the account's catalogue copy,
-- management systems, context, the clause checklist, controlled documents, certificates, external audits and ISO files.
-- Generated by drizzle-kit, then the custom part at the end (forced RLS, grants, triggers, the purge list).

-- A list of ids holds no id twice (standardIds and clauseIds, model §1.4). The table checks below call it.
CREATE FUNCTION canopy_ids_distinct(ids uuid[]) RETURNS boolean
LANGUAGE sql IMMUTABLE PARALLEL SAFE
SET search_path = pg_catalog
AS $$
  SELECT count(DISTINCT x) = count(*) FROM unnest(ids) AS x
$$;
--> statement-breakpoint
