CREATE TABLE "certification" (
	"id" uuid PRIMARY KEY DEFAULT canopy_uuid_v7() NOT NULL,
	"firm_id" uuid DEFAULT app_firm_id() NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"archived_at" timestamp with time zone,
	"version" integer DEFAULT 1 NOT NULL,
	"client_id" uuid NOT NULL,
	"management_system_id" uuid NOT NULL,
	"standard_id" uuid NOT NULL,
	"body" text NOT NULL,
	"certificate_number" text,
	"issued_on" date,
	"expires_on" date,
	"scope_text" text,
	CONSTRAINT "certification_scope_key" UNIQUE("firm_id","client_id","id"),
	CONSTRAINT "certification_issued_check" CHECK ((issued_on is null) = (expires_on is null) and (issued_on is null) = (certificate_number is null) and (expires_on is null or expires_on > issued_on)),
	CONSTRAINT "certification_version_check" CHECK (version >= 1)
);
