	"version" integer DEFAULT 1 NOT NULL,
	"client_id" uuid NOT NULL,
	"management_system_id" uuid NOT NULL,
	"clause_id" uuid NOT NULL,
	"status" "clause_status" DEFAULT 'NOT_STARTED' NOT NULL,
	"justification" text,
	"na_state" "clause_na_state" DEFAULT 'NONE' NOT NULL,
	"status_before_na" "clause_status",
	"na_requested_by_id" uuid,
	"na_decided_by_id" uuid,
	"na_decided_at" timestamp with time zone,
	"owner_id" uuid,
	"notes" text,
	"last_reviewed_on" date,
	CONSTRAINT "clause_assessment_scope_key" UNIQUE("firm_id","client_id","id"),
	CONSTRAINT "clause_assessment_clause_key" UNIQUE("management_system_id","clause_id"),
	CONSTRAINT "clause_assessment_na_status_check" CHECK ((status = 'NOT_APPLICABLE') = (na_state in ('REQUESTED', 'APPROVED'))),
	CONSTRAINT "clause_assessment_na_open_check" CHECK (na_state not in ('REQUESTED', 'APPROVED') or (justification is not null and status_before_na is not null and na_requested_by_id is not null)),
	CONSTRAINT "clause_assessment_status_before_na_check" CHECK (status_before_na is null or status_before_na <> 'NOT_APPLICABLE'),
	CONSTRAINT "clause_assessment_na_decided_check" CHECK ((na_decided_by_id is null) = (na_decided_at is null) and (na_state not in ('APPROVED', 'REJECTED') or (na_decided_by_id is not null and na_decided_by_id is distinct from na_requested_by_id))),
	CONSTRAINT "clause_assessment_version_check" CHECK (version >= 1)
);
