-- A document's current revision is an APPROVED revision of that document, in its client (model §3.4). A trigger rather
-- than a foreign key: the two tables would reference each other, and the account purge could delete neither first.
CREATE FUNCTION canopy_document_current_revision() RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
  IF NEW.current_revision_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM document_revision r
    WHERE r.id = NEW.current_revision_id AND r.firm_id = NEW.firm_id AND r.client_id = NEW.client_id
      AND r.document_id = NEW.id AND r.state = 'APPROVED') THEN
    RAISE EXCEPTION 'the current revision must be an approved revision of this document'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER "controlled_document_current_revision" BEFORE INSERT OR UPDATE OF "current_revision_id" ON "controlled_document"
  FOR EACH ROW EXECUTE FUNCTION canopy_document_current_revision();--> statement-breakpoint

-- A system's standards only grow, and its climate decision, once made, never returns to undecided (model §3.1). M16
-- answers 400 VALIDATION first; the trigger keeps the rule for every writer.
CREATE FUNCTION canopy_management_system_guard() RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
  IF NOT (NEW.standard_ids @> OLD.standard_ids) THEN
    RAISE EXCEPTION 'a management system''s standards cannot be dropped' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.climate_change_relevant IS NOT NULL AND NEW.climate_change_relevant IS NULL THEN
    RAISE EXCEPTION 'a climate decision cannot return to undecided' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER "management_system_guard" BEFORE UPDATE OF "standard_ids", "climate_change_relevant" ON "management_system"
  FOR EACH ROW EXECUTE FUNCTION canopy_management_system_guard();--> statement-breakpoint

-- The account purge (ADR M15-0002, migration 0035) covers the new tables: listed children first, each with the
-- purge role's grants and policies.
CREATE OR REPLACE FUNCTION canopy_purge_tables() RETURNS text[]
LANGUAGE sql IMMUTABLE
SET search_path = public, pg_temp
AS $$
  SELECT ARRAY[
    'iso_file', 'certification_unit', 'certification', 'external_audit', 'document_revision', 'controlled_document',
    'clause_assessment', 'context_item', 'management_system_unit', 'management_system',
    'iso_review_output_def', 'iso_review_input_def', 'iso_clause', 'iso_standard',
    'auth_token', 'auth_session', 'auth_credential', 'idempotency_key', 'notification_send',
    'import_issue', 'import_row', 'import_batch', 'mapping_template', 'export_job',
    'evidence', 'comment', 'compliance_instance', 'assignment', 'obligation', 'act', 'category',
    'unit', 'company', 'location', 'department', 'auth_invite', 'support_grant', 'membership',
    'audit_event', 'domain_event', 'person', 'client'
  ]::text[]
$$;
--> statement-breakpoint
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['iso_file', 'certification_unit', 'certification', 'external_audit', 'document_revision',
    'controlled_document', 'clause_assessment', 'context_item', 'management_system_unit', 'management_system',
    'iso_review_output_def', 'iso_review_input_def', 'iso_clause', 'iso_standard'] LOOP
    EXECUTE format('GRANT SELECT ("firm_id"), DELETE ON %I TO canopy_purge', t);
    EXECUTE format('CREATE POLICY purge_read ON %I FOR SELECT TO canopy_purge USING (firm_id = app_firm_id())', t);
    EXECUTE format('CREATE POLICY purge_delete ON %I FOR DELETE TO canopy_purge USING (firm_id = app_firm_id())', t);
  END LOOP;
END
$$;
